const uuid = (description: string) => ({ type: "string", format: "uuid", description });
const text = (description: string, maxLength = 4_000) => ({ type: "string", minLength: 1, maxLength, description });
const optionalText = (description: string, maxLength = 4_000) => ({ type: "string", maxLength, description });
const integer = (description: string, minimum = 0, maximum = Number.MAX_SAFE_INTEGER) => ({ type: "integer", minimum, maximum, description });
const number = (description: string, minimum = -Number.MAX_VALUE, maximum = Number.MAX_VALUE) => ({ type: "number", minimum, maximum, description });
const boolean = (description: string) => ({ type: "boolean", description });
const dateTime = (description: string) => ({ type: "string", format: "date-time", description });
const date = (description: string) => ({ type: "string", pattern: "^\\d{4}-\\d{2}-\\d{2}$", description });
const sha256 = (description: string) => ({ type: "string", pattern: "^[a-f0-9]{64}$", description });
const enumString = (description: string, values: readonly string[]) => ({ type: "string", enum: values, description });
const strictObject = (description: string, required: readonly string[], properties: Record<string, Record<string, unknown>>) => ({ type: "object", description, required, properties, additionalProperties: false });
const array = (description: string, items: Record<string, unknown>, maxItems = 200, minItems = 0) => ({ type: "array", items, minItems, maxItems, description });
const stringArray = (description: string, maxItems = 100) => array(description, text("Value.", 500), maxItems);
const evidenceIds = array("Tenant-owned record IDs selected as evidence.", uuid("Evidence record ID."), 500, 1);
const modelId = text("Optional expected workspace-configured model identifier. When omitted, the trusted workspace policy is used; never a credential.", 200);
const externalEvidenceToken = optionalText("Short-lived hosting-layer attestation token for the exact external evidence. Required only when applying the effect, never for dry-run preview.", 4_096);
const idempotencyKey = { type: "string", pattern: "^[A-Za-z0-9._:-]{16,200}$", description: "A retry-safe key unique to this logical mutation." };
const approval = strictObject("Attributed human approval of the exact requested effect.", ["approved", "approvedBy", "approvedAt", "decisionId", "reason"], {
  approved: { const: true },
  approvedBy: text("Approving workspace identity.", 200),
  approvedAt: dateTime("Approval clock."),
  decisionId: { type: "string", pattern: "^[A-Za-z0-9._:-]{16,200}$" },
  reason: text("Reason grounded in reviewed evidence.", 1_000),
});

type Draft = Omit<AdditiveWaveTwoActionDefinition, "inputSchema" | "exampleInput" | "cliExample" | "mcpToolName" | "idempotent" | "requiredScope" | "minimumRole" | "risk" | "destructive" | "externalEffect" | "requiresApproval" | "supportsDryRun" | "effectBoundary" | "promptId" | "promptVersion"> & {
  required: readonly string[];
  properties: Record<string, Record<string, unknown>>;
  example: Record<string, unknown>;
  requiredScope?: AdditiveWaveTwoScope;
  minimumRole?: AdditiveWaveTwoRole;
  risk?: AdditiveWaveTwoRisk;
  destructive?: boolean;
  externalEffect?: AdditiveWaveTwoExternalEffect;
  requiresApproval?: boolean;
  supportsDryRun?: boolean;
};

function define(draft: Draft): AdditiveWaveTwoActionDefinition {
  const {
    required,
    properties: draftProperties,
    example,
    requiredScope,
    minimumRole,
    risk,
    destructive = false,
    externalEffect = draft.operation === "ai" ? "model" : "none",
    requiresApproval = destructive || (draft.operation === "mutation" && !["none", "model"].includes(externalEffect)),
    supportsDryRun = requiresApproval,
    ...base
  } = draft;
  const idempotent = draft.operation !== "read";
  const properties = { ...draftProperties };
  const requiredFields = [...required];
  const exampleInput = { ...example };
  if (idempotent) {
    properties.idempotencyKey = idempotencyKey;
    requiredFields.push("idempotencyKey");
    exampleInput.idempotencyKey = `${draft.moduleId}.${draft.id}.example-0001`;
  }
  if (supportsDryRun) {
    properties.dryRun = boolean("Validate and preview the exact effect without changing domain state.");
    properties.approval = approval;
    requiredFields.push("dryRun");
    exampleInput.dryRun = true;
  }
  const promptId = draft.operation === "ai" ? `${draft.moduleId}.${draft.id}` : undefined;
  const promptVersion = draft.operation === "ai" ? "2026-08-24.1" : undefined;
  const mcpToolName = `${draft.moduleId}_${draft.id.replaceAll("-", "_")}`;
  const cliInput = JSON.stringify(exampleInput).replaceAll("'", "'\\''");
  return {
    ...base,
    requiredScope: requiredScope ?? (draft.operation === "read" ? "read" : draft.operation === "ai" ? "ai" : "write"),
    minimumRole: minimumRole ?? (requiresApproval ? "admin" : draft.operation === "read" ? "viewer" : "member"),
    risk: risk ?? (destructive ? "critical" : requiresApproval ? "high" : draft.operation === "ai" ? "medium" : "low"),
    destructive,
    externalEffect,
    requiresApproval,
    supportsDryRun,
    idempotent,
    effectBoundary: draft.operation === "read" ? "read-only" : draft.operation === "ai" ? "proposal-only" : requiresApproval ? "approved-ledger-command" : "tenant-record",
    inputSchema: { type: "object", required: [...new Set(requiredFields)], properties, additionalProperties: false },
    exampleInput,
    cliExample: `supersuite action ${draft.moduleId} ${draft.id} '${cliInput}'`,
    mcpToolName,
    promptId,
    promptVersion,
  };
}

