export const additiveWaveTwoActions: readonly AdditiveWaveTwoActionDefinition[] = [...events, ...people, ...metering, ...assurance, ...live];

export const additiveWaveTwoActionsByModule = new Map<AdditiveWaveTwoModuleId, readonly AdditiveWaveTwoActionDefinition[]>(
  additiveWaveTwoModules.map((module) => [module.id, additiveWaveTwoActions.filter((action) => action.moduleId === module.id)]),
);

export const additiveWaveTwoModuleById = new Map(additiveWaveTwoModules.map((module) => [module.id, module]));

export function additiveWaveTwoAction(moduleId: string, actionId: string) {
  return additiveWaveTwoActions.find((action) => action.moduleId === moduleId && action.id === actionId);
}

export function isAdditiveWaveTwoModule(moduleId: string): moduleId is AdditiveWaveTwoModuleId {
  return additiveWaveTwoModuleById.has(moduleId as AdditiveWaveTwoModuleId);
}

const planRank: Record<AdditiveWaveTwoPlanId, number> = { none: 0, starter: 1, scale: 2, fleet: 3 };
export function additiveWaveTwoPlanAllows(plan: AdditiveWaveTwoPlanId, moduleId: AdditiveWaveTwoModuleId) {
  const module = additiveWaveTwoModuleById.get(moduleId);
  return Boolean(module && planRank[plan] >= planRank[module.minPlan]);
}
